select l_shipmode,
       sum(case when o_orderpriority = '1-URGENT' or o_orderpriority = '2-HIGH' then 1 else 0 end) as high_line_count,
       sum(case when o_orderpriority <> '1-URGENT' and o_orderpriority <> '2-HIGH' then 1 else 0 end) as low_line_count
from (SELECT "r_regionkey" AS r_regionkey, "r_name" AS r_name, "r_comment" AS r_comment, "__index_level_0__" AS __index_level_0__, "r_nations.n_comment" AS n_comment, "r_nations.n_name" AS n_name, "r_nations.n_nationkey" AS n_nationkey, "r_nations.n_customers.c_acctbal" AS c_acctbal, "r_nations.n_customers.c_address" AS c_address, "r_nations.n_customers.c_comment" AS c_comment, "r_nations.n_customers.c_custkey" AS c_custkey, "r_nations.n_customers.c_mktsegment" AS c_mktsegment, "r_nations.n_customers.c_name" AS c_name, "r_nations.n_customers.c_nationkey" AS c_nationkey, "r_nations.n_customers.c_phone" AS c_phone, "r_nations.n_customers.c_orders.o_clerk" AS o_clerk, "r_nations.n_customers.c_orders.o_comment" AS o_comment, "r_nations.n_customers.c_orders.o_custkey" AS o_custkey, "r_nations.n_customers.c_orders.o_orderdate" AS o_orderdate, "r_nations.n_customers.c_orders.o_orderkey" AS o_orderkey, "r_nations.n_customers.c_orders.o_orderpriority" AS o_orderpriority, "r_nations.n_customers.c_orders.o_orderstatus" AS o_orderstatus, "r_nations.n_customers.c_orders.o_shippriority" AS o_shippriority, "r_nations.n_customers.c_orders.o_totalprice" AS o_totalprice, "r_nations.n_customers.c_orders.o_lineitems.l_comment" AS l_comment, "r_nations.n_customers.c_orders.o_lineitems.l_commitdate" AS l_commitdate, "r_nations.n_customers.c_orders.o_lineitems.l_discount" AS l_discount, "r_nations.n_customers.c_orders.o_lineitems.l_extendedprice" AS l_extendedprice, "r_nations.n_customers.c_orders.o_lineitems.l_linenumber" AS l_linenumber, "r_nations.n_customers.c_orders.o_lineitems.l_linestatus" AS l_linestatus, "r_nations.n_customers.c_orders.o_lineitems.l_orderkey" AS l_orderkey, "r_nations.n_customers.c_orders.o_lineitems.l_partkey" AS l_partkey, "r_nations.n_customers.c_orders.o_lineitems.l_quantity" AS l_quantity, "r_nations.n_customers.c_orders.o_lineitems.l_receiptdate" AS l_receiptdate, "r_nations.n_customers.c_orders.o_lineitems.l_returnflag" AS l_returnflag, "r_nations.n_customers.c_orders.o_lineitems.l_shipdate" AS l_shipdate, "r_nations.n_customers.c_orders.o_lineitems.l_shipinstruct" AS l_shipinstruct, "r_nations.n_customers.c_orders.o_lineitems.l_shipmode" AS l_shipmode, "r_nations.n_customers.c_orders.o_lineitems.l_suppkey" AS l_suppkey, "r_nations.n_customers.c_orders.o_lineitems.l_tax" AS l_tax FROM read_parquet_flat('nestedregion.parquet'))
where l_shipmode in ('MAIL', 'SHIP') and l_commitdate < l_receiptdate and l_shipdate < l_commitdate
  and l_receiptdate >= date '1994-01-01' and l_receiptdate < date '1994-01-01' + interval '1' year
group by l_shipmode order by l_shipmode
